local function getf3xremotething()
	local player = game.Players.LocalPlayer
	local char = player.Character
	local tool
	for i,v in player:GetDescendants() do
		if v.Name == "SyncAPI" and v.Parent:FindFirstChild("Tools") and not v.Parent:FindFirstChild("Tools"):FindFirstChild("Marketplace") then
			tool = v.Parent
		end
	end
	if tool == nil then
		for i,v in player:GetDescendants() do
			if v.Name == "SyncAPI" then
				tool = v.Parent
			end
		end
	end
	if tool ~= nil then
		return tool.SyncAPI.ServerEndpoint
	end
end

local function goobery(yeah)
	local thingy = getf3xremotething()
	if thingy ~= nil then
task.defer(function()
	   return thingy:InvokeServer(unpack(yeah))
end)
	end
end

local function modelmove(m, cf)
	if not m or not m.Parent then return end

	local prim = m.PrimaryPart
	if not prim then
		prim = m:FindFirstChildWhichIsA("BasePart")
		if not prim then return end
		m.PrimaryPart = prim
	end

	local args = {
		[1] = "SyncMove",
		[2] = {}
	}

	for _,v in ipairs(m:GetDescendants()) do
		if v:IsA("BasePart") then
			local offset = prim.CFrame:ToObjectSpace(v.CFrame)
			table.insert(args[2], {
				Part = v,
				CFrame = cf * offset
			})
		end
	end

	goobery(args)
end

