spamoption("Insert Sky", function() 
	local selecteddecal = Decal.Text

	local player = game.Players.LocalPlayer
	local char = player.Character
	local tool
	for i,v in player:GetDescendants() do
		if v.Name == "SyncAPI" and v.Parent:FindFirstChild("Tools") and not v.Parent:FindFirstChild("Tools"):FindFirstChild("Marketplace") then
			tool = v.Parent
		end
	end
	if tool == nil then
		for i,v in player:GetDescendants() do
			if v.Name == "SyncAPI" then
				tool = v.Parent
			end
		end
	end
	remote = tool.SyncAPI.ServerEndpoint
	function _(args)
		return remote:InvokeServer(unpack(args))
	end

function SetCollision(part,boolean)
    local args = {
        [1] = "SyncCollision",
        [2] = {
            [1] = {
                ["Part"] = part,
                ["CanCollide"] = boolean
            }
        }
    }
    _(args)
end
	function Color(part,color)
		local args = {
			[1] = "SyncColor",
			[2] = {
				[1] = {
					["Part"] = part,
					["Color"] = color,
					["UnionColoring"] = false
				}
			}
		}
		_(args)
	end
	function AddMesh(part)
		local args = {
			[1] = "CreateMeshes",
			[2] = {
				[1] = {
					["Part"] = part
				}
			}
		}
		_(args)
	end

	local function SetMesh(part,meshid,texid,size)
		local args = {
			[1] = "SyncMesh",
			[2] = {
				[1] = {
					["Part"] = part,
					["MeshId"] = "rbxassetid://"..meshid,
                                        ["TextureId"] = "rbxassetid://"..texid,
                                        ["Scale"] = size
				}
			}
		}
		_(args)
	end
	local function SetName(part, stringg)
		local args = {
			[1] = "SetName",
			[2] = {
				[1] = part
			},
			[3] = stringg
		}

		_(args)
	end

	function SetLocked(part,boolean)
		local args = {
			[1] = "SetLocked",
			[2] = {
				[1] = part
			},
			[3] = boolean
		}
		_(args)
	end

        local destination = workspace:FindFirstChildOfClass("Terrain")

        if tool ~= nil and tool:FindFirstChild("Tools") and tool:FindFirstChild("Tools"):FindFirstChild("Marketplace") then
           destination = workspace
        end

	function Sky(id)
task.defer(function()
                e = char.HumanoidRootPart.CFrame.x
		f = char.HumanoidRootPart.CFrame.y
		g = char.HumanoidRootPart.CFrame.z
		local skypart = _({"CreatePart","普通",CFrame.new(math.floor(e),math.floor(f),math.floor(g)) + Vector3.new(0,6,0),destination})
				SetName(skypart,youridentifierpleasemakethisunique..youruniqueid)
				AddMesh(skypart)
				SetMesh(skypart,"111891702759441",id,Vector3.new(6000,6000,6000))
                                SetCollision(skypart,false)
				SetLocked(skypart,true)
                Color(skypart,Color3.new(0, 0, 0))
end)
	end
	Sky(selecteddecal)
end)

