			[2] = {
				[1] = part
			}
		}
			remote:InvokeServer(unpack(args))
			end)
	end
	function SetTrans(part,int)
		task.defer(function()
		local args = {
			[1] = "SyncMaterial",
			[2] = {
				[1] = {
					["Part"] = part,
					["Transparency"] = int
				}
			}
		}
			_(args)
			end)
	end
	local function SpawnDecal(part,side)
		task.defer(function()
		local args = {
			[1] = "CreateTextures",
			[2] = {
				[1] = {
					["Part"] = part,
					["Face"] = side,
					["TextureType"] = "Decal"
				}
			}
		}

			_(args)
			end)
	end
	local function AddDecal(part,asset,side)
		task.defer(function()
		local args = {
			[1] = "SyncTexture",
			[2] = {
				[1] = {
					["Part"] = part,
					["Face"] = side,
					["TextureType"] = "Decal",
					["Texture"] = "rbxassetid://".. asset
				}
			}
		}
			_(args)
			end)
	end

	local function particle()
		while true do
			wait(0.3)
			if player.Character and player.Character:FindFirstChild("Humanoid") and player.Character.Humanoid.Health > 0 then
				local hrp = player.Character:FindFirstChild("HumanoidRootPart")
				if not hrp then continue end

				local x = hrp.Position.X + math.random(-60, 60)
				local z = hrp.Position.Z + math.random(-60, 60)
				local y = hrp.Position.Y - 50 

				local spawnPosition = CFrame.new(x, y, z)

				task.defer(function()
					local part = CreatePart(spawnPosition, workspace)

					wait(0.1)

							Resize(part, Vector3.new(6, 6, 0.001), part.CFrame)
							SetCollision(part, false)
							SetTrans(part, 1)

							SpawnDecal(part, Enum.NormalId.Front)
							AddDecal(part, id, Enum.NormalId.Front)

							SpawnDecal(part, Enum.NormalId.Back)
							AddDecal(part, id, Enum.NormalId.Back)

							local up = 90
							for i = 2, up do
								if part and part.Parent then
									local newCF = part.CFrame + Vector3.new(0, 2, 0)
									Resize(part, part.Size, newCF)
									wait(0.03)
								end
							end

							delete(part)
				end)
			else
				break
			end
		end
	end

	coroutine.wrap(particle)()
end)

