spamoption("Insert Player Fake Particles (Made By angira)", function()
	local id = Decal.Text

		local Players = game:GetService("玩家")
		local ReplicatedStorage = game:GetService("ReplicatedStorage")
		local player = Players.LocalPlayer
		local char = player.Character or player.CharacterAdded:Wait()
	
		local tool
	for i, v in player:GetDescendants() do
		if v.Name == "SyncAPI" and v.Parent:FindFirstChild("Tools") and not v.Parent:FindFirstChild("Tools"):FindFirstChild("Marketplace") then
			tool = v.Parent
		end
	end
	if tool == nil then
		for i,v in player:GetDescendants() do
			if v.Name == "SyncAPI" then
				tool = v.Parent
			end
		end
	end
		if not tool then return end
	
		local remote = tool.SyncAPI.ServerEndpoint
	
		local function _(args)
			remote:InvokeServer(unpack(args))
		end
	
		local function CreatePart(cf)
			_({"CreatePart", "普通", cf, workspace})
		end
	
		local function Resize(p, s)
			_({"SyncResize", {{Part = p, Size = s, CFrame = p.CFrame}}})
		end
	
		local function Move(p, cf)
			_({"SyncMove", {{Part = p, CFrame = cf}}})
		end
	
		local function Destroy(p)
			_({"移除", {p}})
		end
	
		local function Collision(p, b)
			_({"SyncCollision", {{Part = p, CanCollide = b}}})
		end
	
		local function Material(p, m)
			_({"SyncMaterial", {{Part = p, Material = m, Transparency = 0}}})
		end
	
		local function Mesh(p, tex, scale)
			_({"CreateMeshes", {{Part = p}}})
			_({"SyncMesh", {{
				Part = p,
				MeshId = "rbxassetid://111891702759441",
				TextureId = "rbxassetid://" .. tex,
				Scale = scale
			}}})
		end
	
		task.wait(1)
		
		local f3x = tool
		local endpoint = f3x.SyncAPI.ServerEndpoint
		local function fastInvoke(args)
			task.spawn(function()
				pcall(function()
					endpoint:InvokeServer(unpack(args))
				end)
			end)
		end
		local function quickPart(cf, size, callback)
			task.spawn(function()
				local p = endpoint:InvokeServer("CreatePart", "普通", CFrame.new(10000,10000,10000), workspace)
				if not p then return end
				fastInvoke({"SyncResize", {{Part = p, CFrame = cf, Size = size}}})
				fastInvoke({"SyncCollision", {{Part = p, CanCollide = false}}})
				if callback then
					callback(p, size)
				end
			end)
		end
		local PARTICLE_TEXTURE = id
		local PARTICLE_SIZE = Vector3.new(4, 4, 0.01)
		local function spawnParticle(head)
			local startCF = head.CFrame + Vector3.new(0, 3, 0)
			quickPart(startCF, PARTICLE_SIZE, function(p, size)
				fastInvoke({"SyncMaterial", {{Part = p, Transparency = 0}}})
				fastInvoke({"CreateMeshes", {{Part = p}}})
				fastInvoke({"SyncMesh", {{Part = p, MeshId = "rbxassetid://111891702759441", TextureId = "rbxassetid://" .. PARTICLE_TEXTURE, Scale = size}}})
				task.spawn(function()
					local baseY = startCF.Position.Y
					for i = 1, 40 do
						fastInvoke({"SyncResize", {{
							Part = p,
							CFrame = CFrame.new(
								head.Position.X,
								baseY + (i * 1.2),
								head.Position.Z
							),
							Size = PARTICLE_SIZE
						}}})
						task.wait(0.08)
					end
					fastInvoke({"移除", {p}})
				end)
			end)
		end
		local function particleLoop(plr)
			while plr.Parent do
				task.wait(0.5)
				local c = plr.Character
				if not c then continue end
				local hum = c:FindFirstChildOfClass("Humanoid")
				local head = c:FindFirstChild("Head")
				if hum and head and hum.Health > 0 then
					spawnParticle(head)
				end
			end
		end
		for _, plr in Players:GetPlayers() do
			task.spawn(particleLoop, plr)
		end
end)

