	local function CreatePart(cf,parent,pt)
		local args = {
			[1] = "CreatePart",
			[2] = pt,
			[3] = cf,
			[4] = parent
		}
		return _(args)
	end

	function Resize(part,size,cf)
		local args = {
			[1] = "SyncResize",
			[2] = {
				[1] = {
					["Part"] = part,
					["CFrame"] = cf,
					["Size"] = size
				}
			}
		}
		_(args)
	end

	function Color(part,color)
		local args = {
			[1] = "SyncColor",
			[2] = {
				[1] = {
					["Part"] = part,
					["Color"] = color,
					["UnionColoring"] = false
				}
			}
		}
		_(args)
	end

	function SetLocked(part,boolean)
		local args = {
			[1] = "SetLocked",
			[2] = {
				[1] = part
			},
			[3] = boolean
		}
		_(args)
	end

	function toptexturecreate(part)
		local args = {
			[1] = "CreateTextures",
			[2] = {
				[1] = {
					["Part"] = part,
					["Face"] = Enum.NormalId.Top,
					["TextureType"] = "Texture"
				}
			}
		}

		_(args)
	end
	function toptextureadd(part,tex)
		local args = {
			[1] = "SyncTexture",
			[2] = {
				[1] = {
					["Part"] = part,
					["Face"] = Enum.NormalId.Top,
					["TextureType"] = "Texture",
					["Texture"] = tex,
					["StudsPerTileV"] = 20,
					["StudsPerTileU"] = 20
				}
			}
		}
		_(args)
	end

	hrpx = math.floor(char.HumanoidRootPart.CFrame.x)
	hrpz = math.floor(char.HumanoidRootPart.CFrame.z)
	hrpy = math.floor(char.HumanoidRootPart.CFrame.y)
	function SpawnBasePlate(tex)
task.defer(function()
		local base = CreatePart(CFrame.new(hrpx,hrpy-20,hrpz),workspace,"Spawn")
					Resize(base,Vector3.new(1000,2,1000),CFrame.new(hrpx,hrpy-20,hrpz))
					Color(base,Color3.new(0, 0, 0))
					toptexturecreate(base)
					toptextureadd(base,"rbxassetid://"..tex)
					SetLocked(base,true)
				end)
	end
	SpawnBasePlate(selecteddecal)

end)

