animatedskybutton("skeleton",function()
	-- Epik skeleton dancing F3X By ItsKittyyyGD

	local player = game.Players.LocalPlayer
	local char = player.Character or player.CharacterAdded:Wait()
	local tool

	for i,v in player:GetDescendants() do
		if v.Name == "SyncAPI" and v.Parent:FindFirstChild("Tools") and not v.Parent:FindFirstChild("Tools"):FindFirstChild("Marketplace") then
			tool = v.Parent
		end
	end
	if tool == nil then
		for i,v in player:GetDescendants() do
			if v.Name == "SyncAPI" then
				tool = v.Parent
			end
		end
	end
	local remote = tool.SyncAPI.ServerEndpoint
	local RunService = game:GetService("RunService")

	function _(args)
		return remote:InvokeServer(unpack(args))
	end

	local function CreatePart(cf, parent)
		local args = {
			[1] = "CreatePart",
			[2] = "普通",
			[3] = cf,
			[4] = parent
		}
		return _(args)
	end

	function SetAnchor(part, boolean)
		local args = {
			[1] = "SyncAnchor",
			[2] = {
				[1] = {
					["Part"] = part,
					["Anchored"] = boolean
				}
			}
		}
		_(args)
	end

	function AddMesh(part)
		local args = {
			[1] = "CreateMeshes",
			[2] = {
				[1] = {
					["Part"] = part
				}
			}
		}
		_(args)
	end

	function SetMesh(part,meshid,texid,size)
		local args = {
			[1] = "SyncMesh",
			[2] = {
				[1] = {
					["Part"] = part,
					["MeshId"] = "rbxassetid://"..meshid,
                                        ["TextureId"] = texid,
                                        ["Scale"] = size
				}
			}
		}
		_(args)
	end

	local function SetTransparency(part, value)
task.spawn(function()
		local args = {
			[1] = "SyncTransparency",
			[2] = {
				[1] = {
					["Part"] = part,
					["Transparency"] = value
				}
			}
		}
		_(args)
end)
	end

	function DestroyPart(part)
		local args = {
			[1] = "移除",
			[2] = {
				[1] = part
			}
		}
		_(args)
	end

	local function SetName(part, stringg)
		local args = {
			[1] = "SetName",
			[2] = {
				[1] = part
			},
			[3] = stringg
		}
		_(args)
	end

	local images = {
		"rbxassetid://169585459",
		"rbxassetid://169585475",
		"rbxassetid://169585485",
		"rbxassetid://169585502",
		"rbxassetid://169585515",
		"rbxassetid://169585502",
		"rbxassetid://169585485",
		"rbxassetid://169585475"
	}

	local skyPart
	local skyLoop
	local frameTime = 1 / 10
	local lastUpdate = 0

	function CreateSky()
		local hrp = char:FindFirstChild("HumanoidRootPart")
		if not hrp then return end

		local cf = hrp.CFrame
		local skyPart = CreatePart(CFrame.new(cf.Position + Vector3.new(0, 6, 0)), workspace)
				AddMesh(skyPart)
				SetMesh(skyPart,"111891702759441",images[1],Vector3.new(6000,6000,6000))
				SetTransparency(skyPart, 1)
                                SetName(skyPart,youridentifierpleasemakethisunique..youruniqueid)

				local index = 1
				skyLoop = RunService.Heartbeat:Connect(function(deltaTime)
					lastUpdate = lastUpdate + deltaTime
					if lastUpdate >= frameTime then
						lastUpdate = 0
						if not skyPart then
							skyLoop:Disconnect()
							return
						end
						SetTransparency(skyPart, 0)
						SetMesh(skyPart,"111891702759441",images[index],Vector3.new(6000,6000,6000))
						index = index % #images + 1
					end
				end)
	end

	function ResetSky()
		if skyPart then
			DestroyPart(skyPart)
			skyPart = nil
		end
		if skyLoop then
			skyLoop:Disconnect()
			skyLoop = nil
		end
		CreateSky()
	end

	player.CharacterAdded:Connect(function(newChar)
		char = newChar
		ResetSky()
	end)

	if char and char:FindFirstChild("Humanoid") then
		char:WaitForChild("Humanoid").Died:Connect(function()
			ResetSky()
		end)
	end

	CreateSky()
end)

