simplebutton("Anti Robloxian", function()
	local player = game.Players.LocalPlayer
	local char = player.Character
	local tool
	for i,v in player:GetDescendants() do
		if v.Name == "SyncAPI" and v.Parent:FindFirstChild("Tools") and not v.Parent:FindFirstChild("Tools"):FindFirstChild("Marketplace") then
			tool = v.Parent
		end
	end
	if tool == nil then
		for i,v in player:GetDescendants() do
			if v.Name == "SyncAPI" then
				tool = v.Parent
			end
		end
	end
	--craaa
	remote = tool.SyncAPI.ServerEndpoint
	function _(args)
		remote:InvokeServer(unpack(args))
	end

	function DestroyPart(part)
		task.defer(function()
			local args = {
				[1] = "移除",
				[2] = {
					[1] = part
				}
			}
			_(args)
		end)
	end
	function AddDecor(part,dec)
		task.defer(function()
			local args = {
				[1] = "CreateDecorations",
				[2] = {
					[1] = {
						["Part"] = part,
						["DecorationType"] = dec
					}
				}
			}
			_(args)
		end)
	end

	function antiroblox()
		Player = game.Players.LocalPlayer
		local dist = 17
		local distance = dist
		if Player then
			c = game.Players:GetChildren()
			for i = 1, #c do
				if c[i].Name ~= Player.Name then
					if c[i]:DistanceFromCharacter(game.Workspace[Player.Name].Torso.Position) <= distance and c[i].Character and c[i].Character:FindFirstChild("Head") then
						DestroyPart(c[i].Character:FindFirstChild("Head"))
						local c2 = c[i].Character:GetChildren()
						for i2 =1, #c2 do
							if c2[i2]:IsA("BasePart") then
								task.defer(function()
									AddDecor(c2[i2],"火焰")
								end)
							end 
						end end end end end
	end

	while wait(0.1) do 
			antiroblox()
	end
end)

