			[1] = "SetLocked",
			[2] = {
				[1] = part
			},
			[3] = boolean
		}
		_(args)
	end
	function Color(part,color)
		local args = {
			[1] = "SyncColor",
			[2] = {
				[1] = {
					["Part"] = part,
					["Color"] = color,
					["UnionColoring"] = false
				}
			}
		}
		_(args)
	end

	local player = game.Players.LocalPlayer
	local char = player.Character or player.CharacterAdded:Wait()
	local humanrFr = char:WaitForChild("HumanoidRootPart")


	local cf = humanrFr.CFrame * CFrame.new(0, -4, 0)

	local pad = remote:InvokeServer("CreatePart", "普通", CFrame.new(10000,10000,10000), workspace)

	AddMesh(pad)
	SetMesh(pad,9095618661,Vector3.new(4, 0.5, 4))

	Color(pad, Color3.fromRGB(170, 0, 170))

	Resize(pad, Vector3.new(16, 1, 16), cf)

	while wait() do
		if pad and humanrFr then
			local newCF = humanrFr.CFrame * CFrame.new(0, -4, 0)
			MovePart(pad, newCF)
		end
	end

end)

simplebutton("Head Shake (vibecoded noooo)", function()
	local player = game.Players.LocalPlayer
	local char = player.Character or player.CharacterAdded:Wait()
	local tool
	for i,v in player:GetDescendants() do
		if v.Name == "SyncAPI" and v.Parent:FindFirstChild("Tools") and not v.Parent:FindFirstChild("Tools"):FindFirstChild("Marketplace") then
			tool = v.Parent
		end
	end
	if tool == nil then
		for i,v in player:GetDescendants() do
			if v.Name == "SyncAPI" then
				tool = v.Parent
			end
		end
	end

		if not tool then
			return
		end
	
			local server = tool:WaitForChild("SyncAPI"):WaitForChild("ServerEndpoint")
	
			local head = char:WaitForChild("Head")
			local headMesh = head:FindFirstChildWhichIsA("SpecialMesh")
			if not headMesh then
				return
			end
	
			local myHats = {}
			for _, thing in ipairs(char:GetChildren()) do
				if thing:IsA("Accessory") and thing:FindFirstChild("Handle") then
					local mesh = thing.Handle:FindFirstChildWhichIsA("SpecialMesh")
					if mesh then
						table.insert(myHats, {
							part = thing.Handle,
							mesh = mesh.MeshId
						})
					end
				end
			end
	
			local time = 1
			local off = 1
			local target = 0
			local smooth = 14
	
			local acc = 0
			local rate = 1/60

local RunService = game:GetService("RunService")
	
			RunService.RenderStepped:Connect(function(dt)
				time = time + dt * 6
				target = math.sin(time) * 0.7
				off = off + (target - off) * dt * smooth
	
				acc = acc + dt
				if acc >= rate then
					acc = 0
	
					local stuff = {
						{
							Part = head,
							MeshId = headMesh.MeshId,
							Offset = Vector3.new(off,0,0)
						}
					}
	
					for _, hat in ipairs(myHats) do
						table.insert(stuff, {
							Part = hat.part,
							MeshId = hat.mesh,
							Offset = Vector3.new(off,0,0)
						})
					end
	
					server:InvokeServer("SyncMesh", stuff)
				end
			end)
end)

simplebutton("Head Spin (also vibecoded noooo)", function()
		local player = game.Players.LocalPlayer
		local char = player.Character or player.CharacterAdded:Wait()
		local tool
	
	for i,v in player:GetDescendants() do
		if v.Name == "SyncAPI" and v.Parent:FindFirstChild("Tools") and not v.Parent:FindFirstChild("Tools"):FindFirstChild("Marketplace") then
			tool = v.Parent
		end
	end
	if tool == nil then
		for i,v in player:GetDescendants() do
			if v.Name == "SyncAPI" then
				tool = v.Parent
			end
		end
	end
	
		if not tool then
			return
		end
	
		local remote = tool.SyncAPI.ServerEndpoint
	
		local head = char:WaitForChild("Head", 5)
		if not head then return end
	
		local headMesh = head:FindFirstChildWhichIsA("SpecialMesh") or head:FindFirstChildWhichIsA("FileMesh")
		if not headMesh then
			return
		end
	
		local hats = {}
		for _, acc in char:GetChildren() do
			if acc:IsA("Accessory") and acc:FindFirstChild("Handle") then
				local h = acc.Handle
				local m = h:FindFirstChildWhichIsA("SpecialMesh") or h:FindFirstChildWhichIsA("FileMesh")
				if m then
					table.insert(hats, {Part = h, MeshId = m.MeshId})
				end
			end
		end
	
		local RunService = game:GetService("RunService")
		local t = 0
	
		RunService.RenderStepped:Connect(function(dt)
			t = t + dt * 4   
	
			-- giro em 360 ai
			local radius = 0.5          -- tamanhho do circulo ai
			local spinX = math.cos(t) * radius
			local spinZ = math.sin(t) * radius
	
			local swayY = math.sin(t * 2.5) * 0.15  
			local swayX_extra = math.sin(t * 1.2) * 0.1
			local swayZ_extra = math.cos(t * 1.5) * 0.1
	
			local offset = Vector3.new(spinX + swayX_extra, swayY, spinZ + swayZ_extra)
	
			local partsToSync = {
				{
					Part = head,
					MeshId = headMesh.MeshId,
					Offset = offset
				}
			}
	
			for _, hat in hats do
				table.insert(partsToSync, {
					Part = hat.Part,
					MeshId = hat.MeshId,
					Offset = offset
				})
			end
	
			remote:InvokeServer("SyncMesh", partsToSync)
		end)
end)

simplebutton("Chicken Arms Animation (by nexlius)", function()
local Plr = game.Players.LocalPlayer
local Char = Plr.Character or Plr.CharacterAdded:Wait()
local Hum = Char:FindFirstChildOfClass("Humanoid")

local Moving = false

local AnimCore = Instance.new("Animation")
AnimCore.AnimationId = "rbxassetid://183695923"

local IdleTrack = Hum:LoadAnimation(AnimCore)
IdleTrack.Priority = Enum.AnimationPriority.Idle
IdleTrack:Play()

local Anim = Instance.new("Animation")
Anim.AnimationId = "rbxassetid://180426354"
local AnimTrack2 = Hum:LoadAnimation(Anim)
AnimTrack2.Priority = Enum.AnimationPriority.Idle

local AnimTrack = Hum:LoadAnimation(AnimCore)
AnimTrack.Priority = Enum.AnimationPriority.Idle

task.spawn(function()
IdleTrack:AdjustSpeed(1.5)
    task.wait(.3)
    IdleTrack:AdjustSpeed(0)
end)

Hum.Running:connect(function(speed)
    if speed > 0 and not Moving then
        Moving = true
        task.spawn(function()
            while Moving do
                local currentSpeed = Hum.WalkSpeed
                
                AnimTrack2:Play()
                IdleTrack:Stop()
                AnimTrack:Play()
                
                if currentSpeed == 50 or currentSpeed==100 then
                     AnimTrack2:AdjustSpeed(4)
                    AnimTrack:AdjustSpeed(7)
                    task.wait(.25)
                    AnimTrack:AdjustSpeed(-7)
                else
AnimTrack2:AdjustSpeed(1)
                    AnimTrack:AdjustSpeed(4)
                    task.wait(.25)
                    AnimTrack:AdjustSpeed(-4)
                end
                task.wait(.25)
            end
        end)
        
    elseif speed == 0 then
        Moving = false
        AnimTrack:Stop()
        AnimTrack2:Stop()
        IdleTrack:Play()
        task.spawn(function()
IdleTrack:AdjustSpeed(1.5)
            task.wait(.3)
            IdleTrack:AdjustSpeed(0)
        end)
    end
end)
end)

