		function swait(t)
			if t then
				for i = 0, t do
					game:GetService('RunService').Stepped:wait(0)
				end
			else
				game:GetService('RunService').Stepped:wait(0)
			end
			return true
		end
		function soundeffect(id, volume, speed, parent, forcewait)
			local func = function()
				local s = Instance.new('Sound')
				s.Name = "SoundEffect"
				s.Volume = volume
				s.PlaybackSpeed = speed
				s.SoundId = id
				s.Looped = false
				s.Parent = parent
				s:Play()
				repeat wait() until not s.Playing
				s:Destroy()
			end
			if forcewait then
				func()
			else
				spawn(func)
			end
		end
		local RunService = game:GetService("RunService")
		function specialsound(id, volume, speed, parent, starts, ends)
			local func = function()
				local s = LoadLibrary("RbxUtility").Create("Sound")()
				s.Name = "SoundEffect"
				s.Volume = volume
				s.PlaybackSpeed = speed
				s.SoundId = id
				s.TimePosition = starts
				s.Looped = false
				s.Parent = parent
				s:Play()
				repeat swait() until s.TimePosition >= ends
				s:Destroy()
			end
			spawn(func)
		end
	
