			end)
		end
	
		local function CreatePart(cf,parent)
			local args = {
				[1] = "CreatePart",
				[2] = "普通",
				[3] = cf,
				[4] = parent
			}
			return _(args)
		end
	
		function MovePart(part,cf)
			local args = {
				[1] = "SyncMove",
				[2] = {
					[1] = {
						["Part"] = part,
						["CFrame"] = cf
					}
				}
			}
			_(args)
		end

