		function light(part)
			task.defer(function()
				if not part or not part:IsA("BasePart") then
					return
				end
				task.defer(function()
					local createArgs = {
						"CreateLights",
						{
							{
								Part = part,
								LightType = "PointLight"
							}
						}
					}   
					local syncArgs = {
						"SyncLighting",
						{
							{
								Part = part,
								LightType = "PointLight",
								Color = Color3.fromRGB(255, 155, 0),
								Brightness = 20,
								Range = 2,
							}
						}
					} 
					task.defer(function()
						_(createArgs)
					end)      
					task.defer(function()
						_(syncArgs)
					end)    
					task.wait()
					if part and part.Parent then
						for i, v in ipairs(part:GetDescendants()) do
							if v:IsA("PointLight") then
								task.defer(function()
									DestroyPart(v)
								end)
							end
						end
					end
				end)
			end)
		end
	
