		end)
		task.defer(function()
			SetMesh(ak, "6951907418")
		end)
		task.defer(function()
			MeshResize(ak,Vector3.new(0.1,0.1,0.1))
		end)
	
		function e()
task.defer(function()
MovePartFull({
{Part=nlarm,CFrame=larm.CFrame},
{Part=nrarm,CFrame=rarm.CFrame},
{Part=nlleg,CFrame=lleg.CFrame},
{Part=nrleg,CFrame=rleg.CFrame},
{Part=ntrs,CFrame=trs.CFrame},
{Part=nhd,CFrame=hd.CFrame},
{Part=ak,CFrame=rarm.CFrame*CFrame.new(0,-1,-0.25)*CFrame.Angles(math.rad(270),math.rad(-180),0)}
})
end)
		end
	
		function FireLaser()
			local sounds = {
				{17.49,17.981267708586},
				{17.490114626798,17.755552823579},
				{18,18.465876732586707476}
			}
			local ids = sounds[math.random(#sounds)]
	
			task.defer(function()
				s=r('Sound',ak)
				s.SoundId='rbxassetid://1174337926'
				s.Volume=3
				s:Play()
				wait(5)
				s:Destroy()
			end)
	
			local laserPart = remote:InvokeServer("CreatePart","普通",CFrame.new(10000,10000,10000),workspace)
	
			task.defer(function()
				Setmate(laserPart, "霓虹")
			end)
			task.defer(function()
				SetCollision(laserPart, false)
			end)
	
			local mouse = player:GetMouse()
			local start = ak.Position + Vector3.new(0.5,0,-0.5)
			local endp = mouse.Hit.p
	
			local ignoreList = {char, ak, nlarm, nrarm, nlleg, nrleg, ntrs, nhd}
	
			local ray = Ray.new(start, (endp-start).unit * 999)
			local hit, position = workspace:FindPartOnRayWithIgnoreList(ray, ignoreList)
			local mag = (start-position).magnitude + 2
	
			task.defer(function()
				Resize(laserPart, Vector3.new(0.1,0.1,mag), CFrame.new())
			end)
			task.defer(function()
				MovePart(laserPart, CFrame.new(start, position) * CFrame.new(0,0,-mag/2))
			end)
	
			task.defer(function()
				Color(laserPart, Color3.new(1,1,0))
			end)
	
			task.defer(function()
				for i = 1,10 do
					task.defer(function()
						SetTrans(laserPart, i/10)
					end)
					wait(0.05)
				end
				task.defer(function()
					DestroyPart(laserPart)
				end)
			end)
	
			task.defer(function()
				if hit then
					local humanoid = hit.Parent:FindFirstChildOfClass("Humanoid")
					if humanoid then
						local playerHit = game.Players:GetPlayerFromCharacter(hit.Parent)
						if playerHit then
							KillTarget(playerHit)
						end
					end
				end
			end)
		end
	
		local mouse = player:GetMouse()
		u.TouchTap:Connect(function(gameProccessed, input)
			if not gameProccessed then return end
			if not char then return end
			if char.Humanoid.Health == 0 then return end
			task.defer(function()
