	local script = Instance.new('LocalScript', TextButton_8)

	script.Parent.MouseButton1Down:Connect(function()
		local player = game.Players.LocalPlayer
		local char = player.Character
		local tool
		for i,v in player:GetDescendants() do
			if v.Name == "SyncAPI" and v.Parent:FindFirstChild("Tools") and not v.Parent:FindFirstChild("Tools"):FindFirstChild("Marketplace") then
				tool = v.Parent
			end
		end
		if tool == nil then
			for i,v in player:GetDescendants() do
				if v.Name == "SyncAPI" then
					tool = v.Parent
				end
			end
		end
		--craaa
		remote = tool.SyncAPI.ServerEndpoint

		local function GetPartsFromSelection(Selection)

			local Parts = {}


			for _, Descendant in pairs(Selection:GetDescendants()) do

				if Descendant:IsA 'BasePart' and Descendant.Name ~= "Terrain" then

					Parts[#Parts + 1] = Descendant

				end

			end


			-- Return parts

			return Parts

		end

		local getfuckedlol = GetPartsFromSelection(workspace)

		local shitass = {}

		for _, Part in pairs(getfuckedlol) do
			-- Create the change request for this part

			table.insert(shitass, { Part = Part, Anchored = true });
		end;


		-- Send the change to the server

		remote:InvokeServer('SyncAnchor', shitass);

	end)
end
coroutine.wrap(AYAZSXA_fake_script)()
