button.MouseButton1Down:Connect(function()
	local function changer(shit)
		task.defer(function()
		local player = game.Players.LocalPlayer
	local char = player.Character
	local tool
	for i,v in player:GetDescendants() do
		if v.Name == "SyncAPI" and v.Parent:FindFirstChild("Tools") and not v.Parent:FindFirstChild("Tools"):FindFirstChild("Marketplace") then
			tool = v.Parent
		end
			end
			if tool == nil then
				for i,v in player:GetDescendants() do
					if v.Name == "SyncAPI" then
						tool = v.Parent
					end
				end
			end
			local args = {
				"移除",
				{
					shit
				}
			}
			tool:WaitForChild("SyncAPI"):WaitForChild("ServerEndpoint"):InvokeServer(unpack(args))
		end)
	end

	local function claim(shit)
		task.defer(function()
			local args = {
				game:GetService("ReplicatedStorage"):WaitForChild("raidRoleplay"):WaitForChild("Modules"):WaitForChild("PartOwnership"),
				{
					shit
				}
			}
			game:GetService("ReplicatedStorage"):WaitForChild("raidRoleplay"):WaitForChild("Events"):WaitForChild("EscalateEvent"):FireServer(unpack(args))
		end)
	end


	local mouse = game.Players.LocalPlayer:GetMouse()
	local selectionbox = Instance.new("SelectionBox", workspace)
	local equipped = false
	local oldmouse = mouse.Icon
	local destroytool = Instance.new("Tool", game.Players.LocalPlayer:FindFirstChildOfClass("Backpack"))
	destroytool.RequiresHandle = false
	destroytool.Name = "Delete"
	destroytool.ToolTip = "from Harked Reborn V2"
	destroytool.TextureId = "rbxassetid://12223874"
	destroytool.CanBeDropped = false
	destroytool.Equipped:connect(function()
		equipped = true
		mouse.Icon = "rbxasset://textures\\HammerCursor.png"
		while equipped do
			selectionbox.Adornee = mouse.Target
			wait()
		end
	end)
	destroytool.Unequipped:connect(function()
		equipped = false
		selectionbox.Adornee = nil
		mouse.Icon = oldmouse
		print(oldmouse)
	end)
	destroytool.Activated:connect(function()
if mouse.Target ~= nil then
		local explosion = Instance.new("Explosion", workspace)
		explosion.BlastPressure = 0
		explosion.BlastRadius = 0
		explosion.DestroyJointRadiusPercent = 0
		explosion.ExplosionType = Enum.ExplosionType.NoCraters
		explosion.Position = mouse.Target.Position
		task.defer(function()
			claim(mouse.Target)
			changer(mouse.Target)
		end)
end
	end)
	game:GetService("StarterGui"):SetCoreGuiEnabled('Backpack', true)
end)

